import { existsSync as existsSync4, readFileSync as readFileSync6 } from "node:fs";
import path10 from "node:path";
function writeEnvironmentFile(root, file3, variables) {
  const destination = path10.join(root, file3);
  let content = existsSync4(destination) ? readFileSync6(destination, "utf8") : "";
  const keys = new Set(
    [...content.matchAll(/^[ \t]*(?:export[ \t]+)?([A-Z][A-Z0-9_]*)[ \t]*=/gm)].map(
      (match) => match[1]
    )
  );
  const additions = Object.entries(variables).filter(([key]) => !keys.has(key)).map(([key, value]) => `${key}=${value}`);
  if (additions.length) {
    if (content && !content.endsWith("\n")) content += "\n";
    content += additions.join("\n") + "\n";
  }
  put(root, file3, content || "\n");
}

