// ../../../src/auth-schema.ts
function writeBetterAuthSchema(root, postgres) {
  const table = postgres ? "pgTable" : "sqliteTable";
  const date9 = (column) => postgres ? `timestamp('${column}', { withTimezone: true })` : `integer('${column}', { mode: 'timestamp_ms' })`;
  const bool = postgres ? "boolean('email_verified')" : "integer('email_verified', { mode: 'boolean' })";
  const updated = `${date9("updated_at")}.notNull().$defaultFn(() => new Date()).$onUpdate(() => new Date())`;
  const created = `${date9("created_at")}.notNull().$defaultFn(() => new Date())`;
  const schema = `import { ${table}, text, ${postgres ? "timestamp, boolean" : "integer"}, index } from 'drizzle-orm/${postgres ? "pg-core" : "sqlite-core"}';
export const user = ${table}('user', {
  id: text('id').primaryKey(), name: text('name').notNull(), email: text('email').notNull().unique(),
  emailVerified: ${bool}.notNull().default(false), image: text('image'), createdAt: ${created}, updatedAt: ${updated},
});
export const session = ${table}('session', {
  id: text('id').primaryKey(), expiresAt: ${date9("expires_at")}.notNull(), token: text('token').notNull().unique(),
  createdAt: ${created}, updatedAt: ${updated}, ipAddress: text('ip_address'), userAgent: text('user_agent'),
  userId: text('user_id').notNull().references(() => user.id, { onDelete: 'cascade' }),
}, (table) => [index('session_user_id_idx').on(table.userId)]);
export const account = ${table}('account', {
  id: text('id').primaryKey(), accountId: text('account_id').notNull(), providerId: text('provider_id').notNull(),
  userId: text('user_id').notNull().references(() => user.id, { onDelete: 'cascade' }),
  accessToken: text('access_token'), refreshToken: text('refresh_token'), idToken: text('id_token'),
  accessTokenExpiresAt: ${date9("access_token_expires_at")}, refreshTokenExpiresAt: ${date9("refresh_token_expires_at")},
  scope: text('scope'), password: text('password'), createdAt: ${created}, updatedAt: ${updated},
}, (table) => [index('account_user_id_idx').on(table.userId)]);
export const verification = ${table}('verification', {
  id: text('id').primaryKey(), identifier: text('identifier').notNull(), value: text('value').notNull(),
  expiresAt: ${date9("expires_at")}.notNull(), createdAt: ${created}, updatedAt: ${updated},
}, (table) => [index('verification_identifier_idx').on(table.identifier)]);
`;
  writeFile(path11.join(root, "packages/db/src/schema.ts"), schema);
  if (!postgres) {
    writeFile(
      path11.join(root, "packages/db/drizzle/meta/0000_snapshot.json"),
      JSON.stringify(betterAuthSqliteSnapshot, null, 2) + "\n"
    );
    writeFile(
      path11.join(root, "packages/db/drizzle/meta/_journal.json"),
      JSON.stringify(
        {
          version: "7",
          dialect: "sqlite",
          entries: [
            {
              idx: 0,
              version: "6",
              when: 1791504e6,
              tag: "0000_better_auth",
              breakpoints: true
            }
          ]
        },
        null,
        2
      ) + "\n"
    );
  }
  if (!postgres)
    writeFile(
      path11.join(root, "packages/db/drizzle/0000_better_auth.sql"),
      "CREATE TABLE `account` (\n	`id` text PRIMARY KEY NOT NULL,\n	`account_id` text NOT NULL,\n	`provider_id` text NOT NULL,\n	`user_id` text NOT NULL,\n	`access_token` text,\n	`refresh_token` text,\n	`id_token` text,\n	`access_token_expires_at` integer,\n	`refresh_token_expires_at` integer,\n	`scope` text,\n	`password` text,\n	`created_at` integer NOT NULL,\n	`updated_at` integer NOT NULL,\n	FOREIGN KEY (`user_id`) REFERENCES `user`(`id`) ON UPDATE no action ON DELETE cascade\n);\n--> statement-breakpoint\nCREATE INDEX `account_user_id_idx` ON `account` (`user_id`);--> statement-breakpoint\nCREATE TABLE `session` (\n	`id` text PRIMARY KEY NOT NULL,\n	`expires_at` integer NOT NULL,\n	`token` text NOT NULL,\n	`created_at` integer NOT NULL,\n	`updated_at` integer NOT NULL,\n	`ip_address` text,\n	`user_agent` text,\n	`user_id` text NOT NULL,\n	FOREIGN KEY (`user_id`) REFERENCES `user`(`id`) ON UPDATE no action ON DELETE cascade\n);\n--> statement-breakpoint\nCREATE UNIQUE INDEX `session_token_unique` ON `session` (`token`);--> statement-breakpoint\nCREATE INDEX `session_user_id_idx` ON `session` (`user_id`);--> statement-breakpoint\nCREATE TABLE `user` (\n	`id` text PRIMARY KEY NOT NULL,\n	`name` text NOT NULL,\n	`email` text NOT NULL,\n	`email_verified` integer DEFAULT false NOT NULL,\n	`image` text,\n	`created_at` integer NOT NULL,\n	`updated_at` integer NOT NULL\n);\n--> statement-breakpoint\nCREATE UNIQUE INDEX `user_email_unique` ON `user` (`email`);--> statement-breakpoint\nCREATE TABLE `verification` (\n	`id` text PRIMARY KEY NOT NULL,\n	`identifier` text NOT NULL,\n	`value` text NOT NULL,\n	`expires_at` integer NOT NULL,\n	`created_at` integer NOT NULL,\n	`updated_at` integer NOT NULL\n);\n--> statement-breakpoint\nCREATE INDEX `verification_identifier_idx` ON `verification` (`identifier`);"
    );
}

// ../../../src/scaffold/auth.ts
function scaffoldBetterAuth({ root, updating }) {
  const scheme = expoAuthScheme(root);
  scaffoldManagedEmail(root);
  writeBetterAuthSchema(root, false);
  sharedPackage(
    root,
    "auth",
    `import { createManagedEmail, type EmailEnvironment } from '@workspace/managed-email';
import { expo } from '@better-auth/expo';
import { betterAuth } from 'better-auth';
import { drizzleAdapter } from '@better-auth/drizzle-adapter';
import type { createDatabase } from '@workspace/db';
export function createAuth(db: ReturnType<typeof createDatabase>, secret: string, baseURL: string, email: EmailEnvironment = {}) {
  const sendEmail = createManagedEmail(email);
  return betterAuth({
    database: drizzleAdapter(db, { provider: 'sqlite', transaction: false }),
    secret, baseURL,
    trustedOrigins: [new URL(baseURL).origin, ${jsString(scheme + "://")}],
    plugins: [expo()],
    emailAndPassword: {
      enabled: true,
      requireEmailVerification: Boolean(sendEmail),
      revokeSessionsOnPasswordReset: true,
      sendResetPassword: sendEmail ? async ({ user, url }) => { await sendEmail('reset-password', user.email, url); } : undefined,
    },
    emailVerification: sendEmail ? {
      sendOnSignUp: true,
      sendVerificationEmail: async ({ user, url }) => { await sendEmail('verify-email', user.email, url); },
    } : undefined,
  });
}
`,
    {
      "better-auth": STACK_DEPENDENCIES["better-auth"],
      "@better-auth/expo": STACK_DEPENDENCIES["@better-auth/expo"],
      "@better-auth/drizzle-adapter": STACK_DEPENDENCIES["@better-auth/drizzle-adapter"],
      "@workspace/db": "workspace:*",
      "@workspace/managed-email": "workspace:*"
    }
  );
  patchPackage(root, "apps/api/package.json", {
    dependencies: {
      "@workspace/auth": "workspace:*",
      "@workspace/managed-email": "workspace:*",
      "@workspace/db": "workspace:*",
      "@workspace/contracts": "workspace:*"
    }
  });
  let source = readFileSync7(path12.join(root, "apps/api/src/index.ts"), "utf8");
  source = "import { createAuth } from '@workspace/auth';\nimport { sessionSchema } from '@workspace/contracts';\n" + source;
  source = source.replace(
    "export default app;",
    `app.get('/api/session', async (c) => {
  c.header('cache-control', 'private, no-store');
  const session = await createAuth(createDatabase(c.env.DB), c.env.BETTER_AUTH_SECRET, c.env.BETTER_AUTH_URL, c.env).api.getSession({ headers: c.req.raw.headers });
  if (!session) return c.json({ error: 'Unauthorized' }, 401);
  return c.json(sessionSchema.parse({ user: session.user }));
});
app.on(['GET', 'POST'], '/api/auth/*', (c) => createAuth(createDatabase(c.env.DB), c.env.BETTER_AUTH_SECRET, c.env.BETTER_AUTH_URL, c.env).handler(c.req.raw));
export default app;`
  );
  put(root, "apps/api/src/index.ts", source);
  writeEnvironmentFile(root, "apps/api/.dev.vars.example", {
    BETTER_AUTH_SECRET: "",
    BETTER_AUTH_URL: "http://localhost:3000",
    ANHEDRAL_EMAIL_SCOPE: "",
    ANHEDRAL_EMAIL_CAPABILITY: ""
  });
  scaffoldExpoAuth(root, scheme, !updating);
  scaffoldPasswordReset(root);
  put(
    root,
    "apps/api/src/secrets.d.ts",
    'import type { EmailEnvironment } from "@workspace/managed-email";\ndeclare global { interface Env extends EmailEnvironment { BETTER_AUTH_SECRET: string; BETTER_AUTH_URL: string } }\n'
  );
}

